import { VOCABULARY_LANGUAGES, type VocabularyLanguage } from './first-words';

/**
 * "AI basics": 40 terms an educated non-specialist meets when reading about artificial
 * intelligence, each with a short, neutral definition, in the 16 UI languages. Term and
 * definition are in the same language (the learning language), like "Capitals".
 *
 * Written for this project (no glossary, dictionary or other third-party text was used).
 * English and German were written first; the other languages are AI-assisted translations
 * that await native-speaker review, like the UI (docs/content/deck-format.md).
 *
 * Conventions:
 * - Term: the established technical term of the language, often a loanword ("Token",
 *   "トークン"); an alternative or abbreviation in brackets where people commonly meet it
 *   ("Künstliche Intelligenz (KI)", "Überanpassung (Overfitting)").
 * - Definition: one sentence, factual and neutral, describing what a system does rather than
 *   claiming it thinks or understands; no brand or product names; English at most 140
 *   characters. A definition never contains its own term, and no two definitions of a language
 *   are the same, so each definition card in Memory matches exactly one term (tested).
 * - Portuguese follows Brazilian usage and Chinese is Simplified, like the UI.
 */
