const GLOSSARIES: Readonly<Record<VocabularyLanguage, Glossary>> = { de, en, nl, es, fr, ru, 'zh-Hans': zhHans, ko, ja, ar, pt, it, pl, tr, uk, hi };

export interface AiTermEntry {
  readonly id: AiTermId;
  readonly terms: Readonly<Record<VocabularyLanguage, string>>;
  readonly definitions: Readonly<Record<VocabularyLanguage, string>>;
}

const pick = (id: AiTermId, index: 0 | 1) =>
  Object.fromEntries(VOCABULARY_LANGUAGES.map((lang) => [lang, GLOSSARIES[lang][id][index]])) as Record<VocabularyLanguage, string>;

/** The deck's terms in a fixed order, each with term and definition in every supported language. */
export const AI_TERMS: readonly AiTermEntry[] = AI_TERM_IDS.map((id) => ({ id, terms: pick(id, 0), definitions: pick(id, 1) }));

export function isAiTermId(value: unknown): value is AiTermId {
  return typeof value === 'string' && (AI_TERM_IDS as readonly string[]).includes(value);
}

/** Term and definition of `id` in `language`, or `undefined` if the deck has no such term. */
export function aiTerm(id: string, language: VocabularyLanguage): { term: string; definition: string } | undefined {
  if (!isAiTermId(id)) return undefined;
  const [term, definition] = GLOSSARIES[language][id];
  return { term, definition };
}
